function canUpgrade() public constant returns (bool) { 
    return true; 
}

function upgrade(uint256 _value) onlyPayloadSize(2 * 32) public { 
    UpgradeAgent agent = UpgradeAgent(upgradeAgent); 
    if(!agent.isUpgradeAgent()) throw; 
    if (agent.originalSupply() != totalSupply) throw; 
    if (value == 0) throw; 
    balances[msg.sender] = safeSub(balances[msg.sender], value); 
    totalSupply = safeSub(totalSupply, value); 
    Upgrade(msg.sender, upgradeAgent, value); 
    agent.upgradeFrom(msg.sender, value); 
}

function getUpgradeState() public constant returns (UpgradeState) { 
    if(!canUpgrade()) return UpgradeState.NotAllowed; 
    else if(address(upgradeAgent) == 0x0) return UpgradeState.WaitingForAgent; 
    else if(totalUpgraded == 0) return UpgradeState.ReadyToUpgrade; 
    else return UpgradeState.Upgrading; 
}

function setUpgradeMaster(address _master) onlyOwner { 
    upgradeMaster = _master; 
}

function mint(address receiver, uint amount) onlyMintAgent { 
    totalSupply = totalSupply + amount; 
    balances[receiver] = safeAdd(balances[receiver], amount); 
    Transfer(0x0, receiver, amount); 
    Minted(receiver, amount); 
